// Helper function to count the number of lower-case letters with odd order in the alphabet
function CountLowerCaseOdd(txt: string): int
    requires txt != null
    ensures 0 <= CountLowerCaseOdd(txt) <= |txt|
{
    var count := 0;
    var i := 0;
    while i < |txt|
        invariant 0 <= i <= |txt|
        invariant count == CountLowerCaseOdd(txt[0..i])
    {
        if (txt[i] >= 'a' && txt[i] <= 'z' && (ord(txt[i]) % 2) == 1) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
